1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { requireUser } from "@/lib/auth/dal";
6	import {
7	  heroAvatarEnabled,
8	  generateHeroImage,
9	  fetchImageAsBase64,
10	} from "@/lib/avatar/gemini";
11	
12	export type AvatarState = { ok?: boolean; error?: string; avatarUrl?: string };
13	
14	const WEEK_MS = 7 * 24 * 60 * 60 * 1000;
15	
16	async function revalidateProfile(username: string | null) {
17	  revalidatePath("/settings/profile");
18	  if (username) revalidatePath(`/u/${username}`);
19	}
20	
21	/** Set the base (normal) photo to the member's GitHub avatar. */
22	export async function useGithubAvatar(): Promise<void> {
23	  const user = await requireUser();
24	  const supabase = await createClient();
25	  const { data: p } = await supabase
26	    .from("profiles")
27	    .select("github_user_id, avatar_preference")
28	    .eq("id", user.id)
29	    .single();
30	  if (!p?.github_user_id) return;
31	
32	  const url = `https://avatars.githubusercontent.com/u/${p.github_user_id}?v=4`;
33	  const patch: Record<string, unknown> = { base_avatar_url: url };
34	  if (p.avatar_preference !== "hero") patch.avatar_url = url;
35	
36	  await supabase.from("profiles").update(patch).eq("id", user.id);
37	  await revalidateProfile(user.username);
38	}
39	
40	/** Upload a photo to use as the base (normal) avatar. */
41	export async function uploadBasePhoto(
42	  _prev: AvatarState,
43	  formData: FormData,
44	): Promise<AvatarState> {
45	  const user = await requireUser();
46	
47	  const file = formData.get("photo");
48	  if (!(file instanceof File) || file.size === 0) {
49	    return { error: "Choose a photo to upload." };
50	  }
51	  if (!file.type.startsWith("image/")) {
52	    return { error: "That file isn't an image." };
53	  }
54	  if (file.size > 4 * 1024 * 1024) {
55	    return { error: "Please keep photos under 4 MB." };
56	  }
57	
58	  const bytes = Buffer.from(await file.arrayBuffer());
59	  const ext = file.type.includes("png")
60	    ? "png"
61	    : file.type.includes("webp")
62	      ? "webp"
63	      : "jpg";
64	  const path = `${user.id}/base-${Date.now()}.${ext}`;
65	
66	  const supabase = await createClient();
67	  const { error: uploadError } = await supabase.storage
68	    .from("avatars")
69	    .upload(path, bytes, { contentType: file.type, upsert: true });
70	  if (uploadError) return { error: uploadError.message };
71	
72	  const publicUrl = supabase.storage.from("avatars").getPublicUrl(path).data
73	    .publicUrl;
74	
75	  const { data: p } = await supabase
76	    .from("profiles")
77	    .select("avatar_preference")
78	    .eq("id", user.id)
79	    .single();
80	  const patch: Record<string, unknown> = { base_avatar_url: publicUrl };
81	  if (p?.avatar_preference !== "hero") patch.avatar_url = publicUrl;
82	
83	  const { error: updateError } = await supabase
84	    .from("profiles")
85	    .update(patch)
86	    .eq("id", user.id);
87	  if (updateError) return { error: updateError.message };
88	
89	  await revalidateProfile(user.username);
90	  return { ok: true, avatarUrl: publicUrl };
91	}
92	
93	/** Choose which avatar to display: 'base' (normal) or 'hero'. */
94	export async function setAvatarPreference(formData: FormData): Promise<void> {
95	  const user = await requireUser();
96	  const pref = formData.get("preference") === "hero" ? "hero" : "base";
97	
98	  const supabase = await createClient();
99	  const { data: p } = await supabase
100	    .from("profiles")
101	    .select("base_avatar_url, hero_avatar_url")
102	    .eq("id", user.id)
103	    .single();
104	
105	  const effective =
106	    pref === "hero" ? (p?.hero_avatar_url ?? p?.base_avatar_url) : p?.base_avatar_url;
107	
108	  await supabase
109	    .from("profiles")
110	    .update({ avatar_preference: pref, avatar_url: effective ?? null })
111	    .eq("id", user.id);
112	  await revalidateProfile(user.username);
113	}
114	
115	/** Set a specific (past) hero image as the active avatar. */
116	export async function setActiveHero(formData: FormData): Promise<void> {
117	  const user = await requireUser();
118	  const url = String(formData.get("url") ?? "");
119	  // Only allow a hero from this member's own avatars folder.
120	  if (!url || !url.includes(`/avatars/${user.id}/`)) return;
121	
122	  const supabase = await createClient();
123	  await supabase
124	    .from("profiles")
125	    .update({
126	      hero_avatar_url: url,
127	      avatar_url: url,
128	      avatar_preference: "hero",
129	    })
130	    .eq("id", user.id);
131	  await revalidateProfile(user.username);
132	}
133	
134	/** Generate a superhero version of the base photo (once per week). */
135	export async function generateHeroAvatar(
136	  _prev: AvatarState,
137	  formData: FormData,
138	): Promise<AvatarState> {
139	  const user = await requireUser();
140	
141	  if (!heroAvatarEnabled()) {
142	    return { error: "Superhero avatars aren't enabled yet." };
143	  }
144	  if (formData.get("consent") !== "on") {
145	    return { error: "Please agree to the notice before generating." };
146	  }
147	
148	  const supabase = await createClient();
149	  const { data: profile } = await supabase
150	    .from("profiles")
151	    .select("base_avatar_url, hero_generated_at")
152	    .eq("id", user.id)
153	    .single();
154	
155	  if (!profile?.base_avatar_url) {
156	    return { error: "Add a photo first (GitHub or upload) to transform." };
157	  }
158	
159	  // Admins/mods can regenerate without limit; members are once per week.
160	  const isAdmin = user.role === "admin" || user.role === "moderator";
161	  if (!isAdmin && profile.hero_generated_at) {
162	    const elapsed = Date.now() - new Date(profile.hero_generated_at).getTime();
163	    if (elapsed < WEEK_MS) {
164	      const next = new Date(
165	        new Date(profile.hero_generated_at).getTime() + WEEK_MS,
166	      );
167	      return {
168	        error: `You can summon a new hero on ${next.toLocaleDateString()}.`,
169	      };
170	    }
171	  }
172	
173	  const source = await fetchImageAsBase64(profile.base_avatar_url);
174	  if (!source) return { error: "Couldn't load your photo to transform." };
175	
176	  const result = await generateHeroImage(source);
177	  if (!result.image) {
178	    return {
179	      error: result.error ?? "Image generation failed — try again in a moment.",
180	    };
181	  }
182	  const generated = result.image;
183	
184	  const bytes = Buffer.from(generated.base64, "base64");
185	  const ext = generated.mimeType.includes("png") ? "png" : "jpg";
186	  const path = `${user.id}/hero-${Date.now()}.${ext}`;
187	
188	  const { error: uploadError } = await supabase.storage
189	    .from("avatars")
190	    .upload(path, bytes, { contentType: generated.mimeType, upsert: true });
191	  if (uploadError) return { error: uploadError.message };
192	
193	  const publicUrl = supabase.storage.from("avatars").getPublicUrl(path).data
194	    .publicUrl;
195	
196	  const { error: updateError } = await supabase
197	    .from("profiles")
198	    .update({
199	      hero_avatar_url: publicUrl,
200	      hero_generated_at: new Date().toISOString(),
201	      avatar_preference: "hero",
202	      avatar_url: publicUrl,
203	    })
204	    .eq("id", user.id);
205	  if (updateError) return { error: updateError.message };
206	
207	  await revalidateProfile(user.username);
208	  return { ok: true, avatarUrl: publicUrl };
209	}
