3	import { headers } from "next/headers";
4	import { redirect } from "next/navigation";
5	import { createClient } from "@/lib/supabase/server";
6	import { safeNext } from "@/lib/auth/redirects";
7	
8	/** Resolve the site origin for auth redirects (env first, then request host). */
9	async function getOrigin() {
10	  const envUrl = process.env.NEXT_PUBLIC_SITE_URL;
11	  if (envUrl) return envUrl.replace(/\/$/, "");
12	  const h = await headers();
13	  const host = h.get("x-forwarded-host") ?? h.get("host");
14	  const proto = h.get("x-forwarded-proto") ?? "https";
15	  return `${proto}://${host}`;
16	}
17	
18	/** Start the GitHub OAuth flow, then redirect the browser to GitHub. */
19	export async function signInWithGithub(formData?: FormData) {
20	  const supabase = await createClient();
21	  const origin = await getOrigin();
22	  const next = safeNext(formData?.get("next"));
23	  const callbackUrl = `${origin}/auth/callback?next=${encodeURIComponent(next)}`;
24	  const { data, error } = await supabase.auth.signInWithOAuth({
25	    provider: "github",
26	    options: {
27	      redirectTo: callbackUrl,
28	      scopes: "read:user user:email",
29	    },
30	  });
31	
32	  if (error) redirect(`/login?error=${encodeURIComponent(error.message)}`);
33	  if (data.url) redirect(data.url);
34	}
35	
36	export async function signOut() {
37	  const supabase = await createClient();
38	  await supabase.auth.signOut();
39	  redirect("/");
40	}
