1	import "server-only";
2	
3	import { createClient } from "@/lib/supabase/server";
4	
5	export type RepoKind = "build" | "recommendation";
6	
7	export type RepoSubmitter = {
8	  username: string | null;
9	  display_name: string | null;
10	  avatar_url: string | null;
11	} | null;
12	
13	type RepoBase = {
14	  id: string;
15	  owner: string;
16	  name: string;
17	  github_url: string;
18	  description: string | null;
19	  homepage_url: string | null;
20	  stars: number | null;
21	  language: string | null;
22	  owner_avatar_url: string | null;
23	  kind: RepoKind;
24	  note: string | null;
25	  submitted_by: string | null;
26	  created_at: string;
27	  submitter: RepoSubmitter;
28	};
29	
30	export type RepoItem = RepoBase & {
31	  reactions: Record<string, number>;
32	  reactionCount: number;
33	  myReactions: string[];
34	};
35	
36	const REPO_SELECT =
37	  "id, owner, name, github_url, description, homepage_url, stars, language, owner_avatar_url, kind, note, submitted_by, created_at, submitter:profiles!repos_submitted_by_fkey ( username, display_name, avatar_url )";
38	
39	export async function listRepos(opts?: {
40	  sort?: "new" | "top";
41	  kind?: RepoKind;
42	}): Promise<RepoItem[]> {
43	  const supabase = await createClient();
44	  const {
45	    data: { user },
46	  } = await supabase.auth.getUser();
47	
48	  let query = supabase.from("repos").select(REPO_SELECT);
49	  if (opts?.kind) query = query.eq("kind", opts.kind);
50	  query = query.order("created_at", { ascending: false }).limit(100);
51	
52	  const { data, error } = await query;
53	  if (error) throw error;
54	
55	  const repos = (data ?? []) as unknown as RepoBase[];
56	  const ids = repos.map((r) => r.id);
57	  if (ids.length === 0) return [];
58	
59	  const { data: reactionRows, error: rErr } = await supabase
60	    .from("repo_reactions")
61	    .select("repo_id, emoji, user_id")
62	    .in("repo_id", ids);
63	  if (rErr) throw rErr;
64	
65	  const agg = new Map<string, { counts: Record<string, number>; mine: string[] }>();
66	  for (const id of ids) agg.set(id, { counts: {}, mine: [] });
67	  for (const row of (reactionRows ?? []) as {
68	    repo_id: string;
69	    emoji: string;
70	    user_id: string;
71	  }[]) {
72	    const entry = agg.get(row.repo_id);
73	    if (!entry) continue;
74	    entry.counts[row.emoji] = (entry.counts[row.emoji] ?? 0) + 1;
75	    if (user && row.user_id === user.id) entry.mine.push(row.emoji);
76	  }
77	
78	  const result: RepoItem[] = repos.map((r) => {
79	    const entry = agg.get(r.id)!;
80	    const reactionCount = Object.values(entry.counts).reduce((a, b) => a + b, 0);
81	    return { ...r, reactions: entry.counts, reactionCount, myReactions: entry.mine };
82	  });
83	
84	  if (opts?.sort === "top") {
85	    result.sort(
86	      (a, b) =>
87	        b.reactionCount - a.reactionCount ||
88	        (a.created_at < b.created_at ? 1 : -1),
89	    );
90	  }
91	  return result;
92	}
93	
94	export type RecentRepo = {
95	  id: string;
96	  owner: string;
97	  name: string;
98	  kind: RepoKind;
99	  note: string | null;
100	  created_at: string;
101	  submitter: { username: string | null; display_name: string | null } | null;
102	};
103	
104	/** Newest repos, for the home activity feed. Public read. */
105	export async function listRecentRepos(limit = 4): Promise<RecentRepo[]> {
106	  const supabase = await createClient();
107	  const { data, error } = await supabase
108	    .from("repos")
109	    .select(
110	      "id, owner, name, kind, note, created_at, submitter:profiles!repos_submitted_by_fkey ( username, display_name )",
111	    )
112	    .order("created_at", { ascending: false })
113	    .limit(limit);
114	  if (error) throw error;
115	  return (data ?? []) as unknown as RecentRepo[];
116	}
