13	export async function submitRepo(
14	  _prev: RepoFormState,
15	  formData: FormData,
16	): Promise<RepoFormState> {
17	  const user = await requireUser();
18	
19	  const parsed = repoSubmitSchema.safeParse({
20	    github_url: formData.get("github_url"),
21	    kind: formData.get("kind"),
22	    note: formData.get("note"),
23	  });
24	  if (!parsed.success) {
25	    return { error: parsed.error.issues[0]?.message ?? "Check the form." };
26	  }
27	
28	  const gh = parseGithubUrl(parsed.data.github_url);
29	  if (!gh) return { error: "That doesn't look like a GitHub repository URL." };
30	
31	  const meta = await fetchRepoMeta(gh.owner, gh.name);
32	
33	  const supabase = await createClient();
34	  const { error } = await supabase.from("repos").insert({
35	    owner: gh.owner.toLowerCase(),
36	    name: gh.name.toLowerCase(),
37	    github_url: `https://github.com/${gh.owner}/${gh.name}`,
38	    description: meta?.description ?? null,
39	    homepage_url: meta?.homepage_url ?? null,
40	    stars: meta?.stars ?? null,
41	    language: meta?.language ?? null,
42	    owner_avatar_url: meta?.owner_avatar_url ?? null,
43	    kind: parsed.data.kind,
44	    note: parsed.data.note && parsed.data.note !== "" ? parsed.data.note : null,
45	    submitted_by: user.id,
46	    last_synced_at: meta ? new Date().toISOString() : null,
47	  });
48	
49	  if (error) {
50	    if (error.code === "23505") return { error: "That repo's already on the board." };
51	    return { error: error.message };
52	  }
53	
54	  revalidatePath("/projects");
55	  redirect("/projects");
56	}
