58	/** Toggle one emoji reaction for the current user on a repo. */
59	export async function toggleReaction(formData: FormData): Promise<void> {
60	  const user = await requireUser();
61	  const repoId = String(formData.get("repo_id") ?? "");
62	  const emoji = String(formData.get("emoji") ?? "");
63	  if (!repoId || !isReactionEmoji(emoji)) return;
64	
65	  const supabase = await createClient();
66	  const { data: existing } = await supabase
67	    .from("repo_reactions")
68	    .select("repo_id")
69	    .eq("repo_id", repoId)
70	    .eq("user_id", user.id)
71	    .eq("emoji", emoji)
72	    .maybeSingle();
73	
74	  if (existing) {
75	    await supabase
76	      .from("repo_reactions")
77	      .delete()
78	      .eq("repo_id", repoId)
79	      .eq("user_id", user.id)
80	      .eq("emoji", emoji);
81	  } else {
82	    await supabase
83	      .from("repo_reactions")
84	      .insert({ repo_id: repoId, user_id: user.id, emoji });
85	  }
86	
87	  revalidatePath("/projects");
88	}
