122	/**
123	 * Filter + sort events for the admin list and count each bucket. Reads the
124	 * current time here (a server helper) so the component render stays pure.
125	 * "Past" means the event has already started, regardless of status; the
126	 * status filters show only still-upcoming events of that status.
127	 */
128	export function filterAdminEvents(
129	  events: EventRow[],
130	  filter: AdminEventFilter,
131	): {
132	  events: EventRow[];
133	  counts: Record<AdminEventFilter, number>;
134	  pastIds: Set<string>;
135	} {
136	  const now = Date.now();
137	  const isPast = (e: EventRow) => new Date(e.starts_at).getTime() < now;
138	  const pastIds = new Set(events.filter(isPast).map((e) => e.id));
139	
140	  const counts: Record<AdminEventFilter, number> = {
141	    all: events.length,
142	    published: events.filter((e) => e.status === "published" && !isPast(e))
143	      .length,
144	    draft: events.filter((e) => e.status === "draft" && !isPast(e)).length,
145	    cancelled: events.filter((e) => e.status === "cancelled" && !isPast(e))
146	      .length,
147	    past: events.filter(isPast).length,
148	  };
149	
150	  const match = (e: EventRow): boolean => {
151	    switch (filter) {
152	      case "all":
153	        return true;
154	      case "past":
155	        return isPast(e);
156	      default:
157	        return e.status === filter && !isPast(e);
158	    }
159	  };
160	
161	  const sorted = events.filter(match).sort((a, b) => {
162	    const ta = new Date(a.starts_at).getTime();
163	    const tb = new Date(b.starts_at).getTime();
164	    // Past: most recent first. Everything else: soonest upcoming first.
165	    return filter === "past" ? tb - ta : ta - tb;
166	  });
167	
168	  return { events: sorted, counts, pastIds };
169	}
