2	//
3	// DECISION (see docs/DECISIONS.md): event times are stored as the admin's
4	// wall-clock interpreted as UTC and are ALWAYS displayed in UTC, so the time
5	// shown equals exactly what the admin entered. The timezone label communicates
6	// the intended zone. Proper multi-timezone conversion is deferred (needs a TZ
7	// library); for a single-community listing this is predictable and bug-free.
8	
9	const TZ_LABELS: Record<string, string> = {
10	  "America/New_York": "ET",
11	  "America/Chicago": "CT",
12	  "America/Denver": "MT",
13	  "America/Los_Angeles": "PT",
14	  "Europe/London": "GMT",
15	  "Europe/Berlin": "CET",
16	  UTC: "UTC",
17	};
18	
19	export function tzLabel(tz?: string | null): string {
20	  if (!tz) return "";
21	  return TZ_LABELS[tz] ?? tz;
22	}
