24	/** Compact parts for the comic date plate on event cards. */
25	export function formatDateParts(iso: string) {
26	  const date = new Date(iso);
27	  const part = (opts: Intl.DateTimeFormatOptions) =>
28	    new Intl.DateTimeFormat("en-US", { ...opts, timeZone: "UTC" }).format(date);
29	  return {
30	    month: part({ month: "short" }).toUpperCase(),
31	    day: part({ day: "2-digit" }),
32	    weekday: part({ weekday: "short" }),
33	    time: part({ hour: "numeric", minute: "2-digit" }),
34	  };
35	}
36	
37	/** Full human date, e.g. "Thursday, October 9, 2026". */
38	export function formatFullDate(iso: string) {
39	  return new Intl.DateTimeFormat("en-US", {
40	    weekday: "long",
41	    month: "long",
42	    day: "numeric",
43	    year: "numeric",
44	    timeZone: "UTC",
45	  }).format(new Date(iso));
46	}
47	
48	/** Time only, e.g. "1:00 PM". */
49	export function formatTime(iso: string) {
50	  return new Intl.DateTimeFormat("en-US", {
51	    hour: "numeric",
52	    minute: "2-digit",
53	    timeZone: "UTC",
54	  }).format(new Date(iso));
55	}
