57	/** Convert a stored UTC ISO timestamp back to a datetime-local input value. */
58	export function toDatetimeLocalValue(iso: string): string {
59	  // Stored as UTC wall-clock; slice to "YYYY-MM-DDTHH:mm".
60	  return iso.slice(0, 16);
