  mode,
  event,
}: {
  mode: "create" | "edit";
  event?: EventRow;
}) {
  const action = mode === "create" ? createEvent : updateEvent;
  const [state, formAction, pending] = useActionState<EventFormState, FormData>(
    action,
    {},
  );
  const [isVirtual, setIsVirtual] = useState(event?.is_virtual ?? true);
  const [recurrence, setRecurrence] = useState<string>(
    event?.recurrence ?? "none",
  );

  return (
    <form action={formAction} className="flex flex-col gap-5">
      {mode === "edit" && event && (
        <input type="hidden" name="id" value={event.id} />
      )}

      <TitleSlugFields
        defaultTitle={event?.title ?? ""}
        defaultSlug={event?.slug ?? ""}
        excludeId={event?.id}
      />

      <Field label="Summary" hint="Short blurb shown on cards (max 200 chars).">
        <input
          name="summary"
          defaultValue={event?.summary ?? ""}
          maxLength={200}
          placeholder="What this session is about, in a sentence."
          className={inputClass}
        />
      </Field>

      <Field label="Description">
        <textarea
          name="description"
          rows={5}
          defaultValue={event?.description ?? ""}
          placeholder="The full details."
          className={inputClass}
        />
      </Field>

      <div className="grid gap-5">
        <Field label="Starts" hint="Interpreted as the timezone below.">
          <ComicDateTimePicker
            name="starts_at"
            defaultValue={event ? toDatetimeLocalValue(event.starts_at) : undefined}
          />
        </Field>
        <Field label="Ends (optional)">
          <ComicDateTimePicker
            name="ends_at"
            defaultValue={
              event?.ends_at ? toDatetimeLocalValue(event.ends_at) : undefined
            }
          />
        </Field>
      </div>

      <Field label="Timezone">
        <ChoiceChips
          name="timezone"
          defaultValue={event?.timezone ?? "America/New_York"}
          options={[
            { value: "America/New_York", label: "Eastern" },
            { value: "America/Chicago", label: "Central" },
            { value: "America/Denver", label: "Mountain" },
            { value: "America/Los_Angeles", label: "Pacific" },
            { value: "UTC", label: "UTC" },
            { value: "Europe/London", label: "London" },
            { value: "Europe/Berlin", label: "Berlin" },
          ]}
        />
      </Field>

      <Field label="Format">
        <ChoiceChips
          name="is_virtual"
          defaultValue={isVirtual ? "true" : "false"}
          onChange={(v) => setIsVirtual(v === "true")}
          options={[
            { value: "true", label: "Virtual" },
            { value: "false", label: "In person" },
          ]}
        />
      </Field>

      {isVirtual ? (
        <Field
          label="Event URL"
          hint="Where attendees join — Zoom, Meet, a stream link, etc."
        >
          <input
            name="url"
            type="url"
            defaultValue={event?.url ?? ""}
            placeholder="https://…"
            className={inputClass}
          />
        </Field>
      ) : (
        <Field label="Location" hint="Venue name and/or address.">
          <input
            name="location"
            defaultValue={event?.location ?? ""}
            placeholder="Venue, city"
            className={inputClass}
          />
        </Field>
      )}

      <Field label="Session type" hint="Shown on event cards.">
        <ChoiceChips
          name="host"
          defaultValue={event?.host ?? "Live build stream"}
          options={[
            { value: "Live build stream", label: "Live build stream" },
            { value: "Community roundtable", label: "Community roundtable" },
            { value: "Workshop", label: "Workshop" },
            { value: "Talk", label: "Talk" },
            { value: "Q&A", label: "Q&A" },
            { value: "Social", label: "Social" },
          ]}
        />
      </Field>

      <Field
        label="Repeats"
        hint="Recurring events repeat automatically in subscribers' calendars."
      >
        <ChoiceChips
          name="recurrence"
          defaultValue={event?.recurrence ?? "none"}
          onChange={(v) => setRecurrence(v)}
          options={[
            { value: "none", label: "Never" },
            { value: "weekly", label: "Weekly" },
            { value: "biweekly", label: "Every 2 weeks" },
            { value: "monthly", label: "Monthly" },
            { value: "daily", label: "Daily" },
          ]}
        />
      </Field>

      {recurrence !== "none" && (
        <Field label="Repeat until" hint="Leave blank to repeat indefinitely.">
          <ComicDateTimePicker
            name="recurrence_until"
            dateOnly
            defaultValue={event?.recurrence_until ?? undefined}
          />
        </Field>
      )}

      <div className="grid gap-5 sm:grid-cols-2">
        <Field label="Accent">
          <ColorSwatches
            name="accent"
            defaultValue={event?.accent ?? "blue"}
            options={[
              { value: "blue", label: "Blue" },
              { value: "lime", label: "Lime" },
              { value: "purple", label: "Purple" },
            ]}
          />
        </Field>
        <Field label="Status" hint="Only published events are public.">
          <ChoiceChips
            name="status"
            defaultValue={event?.status ?? "draft"}
            options={[
              { value: "draft", label: "Draft" },
              { value: "published", label: "Published" },
              { value: "cancelled", label: "Cancelled" },
            ]}
          />
        </Field>
      </div>

      <div className="flex items-center gap-4">
        <ComicButton variant="blue" type="submit" disabled={pending}>
          {pending
            ? "Saving…"
            : mode === "create"
              ? "Create event"
              : "Save changes"}
        </ComicButton>
        {state.error && (
          <span className="text-sm text-brand-purple">{state.error}</span>
        )}
      </div>
    </form>
  );
}

